/** Foundation tables are written exclusively through controlled operations. */
type ReadOnlyTable<Row, Relationships extends { foreignKeyName: string; columns: string[]; isOneToOne: boolean; referencedRelation: string; referencedColumns: string[] }[] = []> = { Row: Row; Insert: never; Update: never; Relationships: Relationships };
export type FoundationTables = {
  // Migration 0135 (resident iOS Phase 17): a resident reads their own inbox and may change `read_at` only.
  notification_inbox: {
    Row: NotificationInboxRow; Insert: never; Update: { read_at?: string | null };
    Relationships: [{ foreignKeyName: 'notification_inbox_recipient_id_fkey'; columns: ['recipient_id']; isOneToOne: false; referencedRelation: 'profiles'; referencedColumns: ['id'] }];
  };
  notification_preferences: ReadOnlyTable<{ user_id: string; kinds: Json; updated_at: string }, [
    { foreignKeyName: 'notification_preferences_user_id_fkey'; columns: ['user_id']; isOneToOne: true; referencedRelation: 'profiles'; referencedColumns: ['id'] },
  ]>;
  service_request_sla_alerts: ReadOnlyTable<{
    id: string; request_id: string; threshold: 'near_target' | 'overdue';
    evaluated_at: string; agency_seconds: number;
  }, [
    { foreignKeyName: 'service_request_sla_alerts_request_id_fkey'; columns: ['request_id']; isOneToOne: false; referencedRelation: 'service_requests'; referencedColumns: ['id'] },
  ]>;
  barangay_localities: ReadOnlyTable<{ barangay_id: string; display_name: string; city: string; province: string; resident_registration_enabled: boolean }, [
    { foreignKeyName: 'barangay_localities_barangay_id_fkey'; columns: ['barangay_id']; isOneToOne: true; referencedRelation: 'barangays'; referencedColumns: ['id'] },
  ]>;
  id_submissions: ReadOnlyTable<IdSubmissionRow, [
    { foreignKeyName: 'id_submissions_barangay_id_fkey'; columns: ['barangay_id']; isOneToOne: false; referencedRelation: 'barangays'; referencedColumns: ['id'] },
    { foreignKeyName: 'id_submissions_resident_id_fkey'; columns: ['resident_id']; isOneToOne: false; referencedRelation: 'profiles'; referencedColumns: ['id'] },
    { foreignKeyName: 'id_submissions_reviewed_by_fkey'; columns: ['reviewed_by']; isOneToOne: false; referencedRelation: 'profiles'; referencedColumns: ['id'] },
  ]>;
  request_attachments: ReadOnlyTable<RequestAttachmentRow, [
    { foreignKeyName: 'request_attachments_barangay_id_fkey'; columns: ['barangay_id']; isOneToOne: false; referencedRelation: 'barangays'; referencedColumns: ['id'] },
    { foreignKeyName: 'request_attachments_request_id_fkey'; columns: ['request_id']; isOneToOne: false; referencedRelation: 'service_requests'; referencedColumns: ['id'] },
    { foreignKeyName: 'request_attachments_resident_id_fkey'; columns: ['resident_id']; isOneToOne: false; referencedRelation: 'profiles'; referencedColumns: ['id'] },
  ]>;
  service_request_pauses: ReadOnlyTable<ServiceRequestPauseRow, [
    { foreignKeyName: 'service_request_pauses_request_id_fkey'; columns: ['request_id']; isOneToOne: false; referencedRelation: 'service_requests'; referencedColumns: ['id'] },
    { foreignKeyName: 'service_request_pauses_resumed_by_fkey'; columns: ['resumed_by']; isOneToOne: false; referencedRelation: 'profiles'; referencedColumns: ['id'] },
    { foreignKeyName: 'service_request_pauses_started_by_fkey'; columns: ['started_by']; isOneToOne: false; referencedRelation: 'profiles'; referencedColumns: ['id'] },
  ]>;
};
type FoundationOperation = { Args: { p_input: Json }; Returns: string };
export type FoundationFunctions = ResidentAccountSetupFunctions & {
  incomplete_profile_browsing_barangay: { Args: Record<string, never>; Returns: string | null };
  service_request_sla_tracking: { Args: { p_request_id: string }; Returns: Json };
  service_request_sla_metrics: { Args: { p_request_id: string; p_at?: string }; Returns: Json };
  service_sla_report_rows: { Args: Record<string, never>; Returns: Json };
  set_service_request_pages: { Args: { p_request_id: string; p_total_pages: number }; Returns: undefined };
  collect_tax_code_pickup_payment: { Args: { p_request_id: string; p_amount_centavos: number }; Returns: string };
  start_pickup_payment: { Args: { p_request_id: string }; Returns: string };
  collect_pickup_payment: { Args: { p_request_id: string }; Returns: string };
  complete_resident_profile: FoundationOperation;
  publish_id_submission: FoundationOperation;
  review_id_submission: FoundationOperation;
  submit_service_request: FoundationOperation;
  assess_service_request_fee: FoundationOperation;
  review_service_request: FoundationOperation;
  transition_service_request_sla: FoundationOperation;
};// Notification sender (Resident iOS Phase 17, P17-T02). Run on a schedule by the operations owner
// (for example every minute from pg_cron + pg_net, or an external scheduler).
//
// This is not a resident-callable function: it has no user JWT. Gateway JWT verification is off
// (any signed-in resident's token would pass it), and the caller must present the shared secret
// in `x-worker-secret`. Without NOTIFICATION_WORKER_SECRET configured the function refuses to run.
//
// Secrets (set by the operations owner, never committed):
//   NOTIFICATION_WORKER_SECRET  shared secret with the scheduler
//   EXPO_ACCESS_TOKEN           optional, when Expo "enhanced push security" is enabled
// The service-role key and URL are provided by the Edge runtime. Push tokens, ticket ids and
// message text are never logged or returned.
import { createClient } from 'jsr:@supabase/supabase-js@2';
import { runWorker, type Fetcher, type Rpc } from './worker.ts';

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

function secretMatches(provided: string | null, expected: string): boolean {
  if (!provided) return false;
  const a = new TextEncoder().encode(provided);
  const b = new TextEncoder().encode(expected);
  // Constant-time comparison over the longer length; unequal lengths always fail.
  let difference = a.length ^ b.length;
  for (let index = 0; index < Math.max(a.length, b.length); index++) difference |= (a[index] ?? 0) ^ (b[index] ?? 0);
  return difference === 0;
}

Deno.serve(async (request: Request) => {
  if (request.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);
  const secret = Deno.env.get('NOTIFICATION_WORKER_SECRET');
  if (!secret) return json({ error: 'not_configured' }, 503);
  if (!secretMatches(request.headers.get('x-worker-secret'), secret)) return json({ error: 'unauthorized' }, 401);

  const url = Deno.env.get('SUPABASE_URL');
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !serviceKey) return json({ error: 'not_configured' }, 503);
  const client = createClient(url, serviceKey, { auth: { persistSession: false, autoRefreshToken: false } });

  const rpc: Rpc = async (name, args) => {
    const { data, error } = await client.rpc(name, args ?? {});
    return { data, error: error ? { message: error.message } : null };
  };
  const send: Fetcher = (target, init) => fetch(target, init);
  const summary = await runWorker({ rpc, fetch: send, accessToken: Deno.env.get('EXPO_ACCESS_TOKEN') || undefined });
  return json(summary, summary.errors.length ? 207 : 200);
});begin;

-- A previously confirmed address cannot lend its badge to an edited address.
-- Run after guard_verification_fields: resident-written status changes still
-- fail, while this server-owned trigger resets status on a permitted email edit.
create function barangayan_private.reset_changed_profile_email_verification()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if lower(btrim(coalesce(new.email,''))) is distinct from lower(btrim(coalesce(old.email,''))) then
  new.email_verification_status := 'unverified';
  new.email_verification_requested_at := null;
  new.email_verified_at := null;
 end if;
 return new;
end $$;
revoke all on function barangayan_private.reset_changed_profile_email_verification() from public,anon,authenticated,service_role;
create trigger reset_changed_profile_email_verification before update of email on public.profiles
for each row execute function barangayan_private.reset_changed_profile_email_verification();

commit;begin;

-- Front-only submissions carry the resident's confirmed, immutable review data.
-- Existing two-sided versions and approval provenance remain intact.
alter table public.id_submissions alter column back_path drop not null;
alter table public.id_submissions add column confirmed_details jsonb;
alter table public.id_submissions add constraint id_submissions_front_details_required
  check (back_path is not null or confirmed_details is not null);

create or replace function barangayan_private.publish_id_submission(p_input jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_actor public.profiles; v_profile public.profiles; v_old public.id_submissions;
  v_id uuid; v_type text; v_front text; v_back text; v_prefix text; v_version integer;
  v_details jsonb; v_name text; v_number text; v_birth text; v_address text;
begin
  v_actor := barangayan_private.assert_actor();
  perform barangayan_private.check_keys(p_input,array['submissionId','idType','frontPath','backPath','confirmedDetails']);
  v_id := barangayan_private.required_text(p_input,'submissionId',36)::uuid;
  v_type := barangayan_private.required_text(p_input,'idType',200);
  v_front := barangayan_private.required_text(p_input,'frontPath',500);
  v_back := barangayan_private.optional_text(p_input,'backPath',500);
  if p_input ? 'confirmedDetails' then
    v_details := p_input->'confirmedDetails';
    perform barangayan_private.check_keys(v_details,array['fullName','idNumber','birthDate','address']);
    v_name := barangayan_private.required_text(v_details,'fullName',200);
    -- Optional front fields use empty strings, never invented profile values.
    if not (v_details ?& array['idNumber','birthDate','address']) then
      raise exception 'invalid_confirmed_details' using errcode='22023';
    end if;
    v_number := barangayan_private.optional_text(v_details,'idNumber',200);
    v_birth := barangayan_private.optional_text(v_details,'birthDate',10);
    v_address := barangayan_private.optional_text(v_details,'address',1000);
    if v_birth is not null then
      if v_birth !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or v_birth like '0000-%' then
        raise exception 'invalid_birth_date' using errcode='22023';
      end if;
      begin
        if to_char(v_birth::date,'YYYY-MM-DD') <> v_birth or v_birth::date > current_date then
          raise exception 'invalid_birth_date' using errcode='22023';
        end if;
      exception when datetime_field_overflow or invalid_datetime_format then
        raise exception 'invalid_birth_date' using errcode='22023';
      end;
    end if;
    v_details := jsonb_build_object('fullName',v_name,'idNumber',coalesce(v_number,''),'birthDate',coalesce(v_birth,''),'address',coalesce(v_address,''));
  elsif v_back is null then
    raise exception 'confirmed_details_required' using errcode='22023';
  end if;
  v_prefix := v_actor.id::text || '/versions/' || v_id::text || '/';
  if v_front !~ ('^' || v_prefix || 'id-front\.(jpg|jpeg|png|webp)$') or
    (v_back is not null and v_back !~ ('^' || v_prefix || 'id-back\.(jpg|jpeg|png|webp)$')) then
    raise exception 'invalid_ID_version_path' using errcode='22023';
  end if;
  select * into v_profile from public.profiles where id=v_actor.id and deleted_at is null for update;
  if not found then raise exception 'forbidden' using errcode='42501'; end if;
  select * into v_old from public.id_submissions where id=v_id;
  if found then
    if v_old.resident_id <> v_actor.id or v_old.id_type <> v_type or v_old.front_path <> v_front
      or v_old.back_path is distinct from v_back or v_old.confirmed_details is distinct from v_details then
      raise exception 'idempotency_conflict' using errcode='22023';
    end if;
    return v_id;
  end if;
  perform barangayan_private.check_object('id-documents',v_front);
  if v_back is not null then perform barangayan_private.check_object('id-documents',v_back); end if;
  select coalesce(max(version),0)+1 into v_version from public.id_submissions where resident_id=v_actor.id;
  insert into public.id_submissions(id,resident_id,barangay_id,version,id_type,front_path,back_path,confirmed_details)
    values(v_id,v_actor.id,v_actor.barangay_id,v_version,v_type,v_front,v_back,v_details);
  update public.profiles set current_id_submission_id=v_id,approved_id_submission_id=null,
    id_type=v_type,id_photo_urls=array_remove(array[v_front,v_back],null),id_verification_status='pending' where id=v_actor.id;
  return v_id;
end $$;

-- Preserve the current service submission implementation (including later
-- migrations), making only its back-evidence check conditional.
do $$
declare v_definition text;
begin
  v_definition := pg_get_functiondef('barangayan_private.submit_service_request(jsonb)'::regprocedure);
  if position('perform barangayan_private.check_object(''id-documents'',s.back_path);' in v_definition) = 0 then
    raise exception 'service_submission_back_check_not_found';
  end if;
  execute replace(v_definition,
    'perform barangayan_private.check_object(''id-documents'',s.back_path);',
    'if s.back_path is not null then perform barangayan_private.check_object(''id-documents'',s.back_path); end if;');
end $$;

-- Limit paid OCR requests atomically per resident. No image/text in this table.
create table barangayan_private.id_extraction_limits (
  resident_id uuid primary key references public.profiles(id) on delete cascade,
  window_start timestamptz not null,
  request_count integer not null check (request_count > 0)
);
alter table barangayan_private.id_extraction_limits enable row level security;
revoke all on barangayan_private.id_extraction_limits from public,anon,authenticated,service_role;
create function public.consume_id_extraction_limit(p_resident_id uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
declare v_window timestamptz := date_bin('1 minute',clock_timestamp(),timestamptz '2000-01-01 00:00:00+00'); v_count integer;
begin
  insert into barangayan_private.id_extraction_limits as l(resident_id,window_start,request_count)
    values(p_resident_id,v_window,1)
    on conflict(resident_id) do update set window_start=v_window,
      request_count=case when l.window_start=v_window then l.request_count+1 else 1 end
    returning request_count into v_count;
  return v_count <= 5;
end $$;
revoke all on function public.consume_id_extraction_limit(uuid) from public,anon,authenticated;
grant execute on function public.consume_id_extraction_limit(uuid) to service_role;

commit;-- Resident iOS Phase 3 (P03-T03): provider-aware account setup for Sign in with Apple.
--
-- Additive. `public.get_resident_account_setup_status()` keeps its strict legacy shape
-- (`registrationOrigin` email_otp | google | legacy) for Android/web; an Apple account
-- is reported there as `legacy` with its true password state, which those clients treat
-- as "recover a password first". iOS consumes the new versioned
-- `public.get_resident_account_setup_status_v2()`.
--
-- Apple Auth-managed identity rows (not editable user metadata) are the only input to
-- profile provisioning, exactly as for Google. Tenant comes from the configured
-- registration locality. No profile detail, completion or ID approval is invented.
begin;

alter table barangayan_private.resident_account_lifecycle
 drop constraint resident_account_lifecycle_registration_origin_check;
alter table barangayan_private.resident_account_lifecycle
 add constraint resident_account_lifecycle_registration_origin_check
 check (registration_origin in ('email_otp','google','apple','legacy'));

-- Same observation logic as 0107 plus the Apple origin. An Apple sign-in carries no
-- password, so its password state is "absent" until a server credential write.
create or replace function barangayan_private.observe_resident_auth_password() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op='INSERT' then
  insert into barangayan_private.resident_account_lifecycle
   (user_id,registration_origin,password_set,password_evidence,creation_transaction)
  values(new.id,
   case when new.raw_user_meta_data->>'resident_registration_origin'='email_otp' then 'email_otp'
    when new.raw_app_meta_data->>'provider'='google' then 'google'
    when new.raw_app_meta_data->>'provider'='apple' then 'apple' else 'legacy' end,
   case when new.raw_user_meta_data->>'resident_registration_origin'='email_otp' or coalesce(new.encrypted_password,'')='' then false else null end,
   case when new.raw_user_meta_data->>'resident_registration_origin'='email_otp' or coalesce(new.encrypted_password,'')='' then 'absent' else 'unknown_initial_hash' end,
   pg_current_xact_id()) on conflict(user_id) do nothing;
 elsif new.encrypted_password is distinct from old.encrypted_password then
  update barangayan_private.resident_account_lifecycle
  set password_set=coalesce(new.encrypted_password,'')<>'',
   password_evidence=case when coalesce(new.encrypted_password,'')='' then 'absent' else 'auth_password_write' end,
   password_observed_at=clock_timestamp()
  where user_id=new.id and creation_transaction is distinct from pg_current_xact_id();
 end if;
 return new;
end $$;

-- Provider-managed identities never import user-editable registration metadata.
create or replace function barangayan_private.guard_profile_locations() returns trigger
language plpgsql security definer set search_path='' as $$
declare geometry jsonb; metadata jsonb; configured uuid;
begin
 select boundary into geometry from public.barangays where id=new.barangay_id;
 if tg_op='INSERT' and new.role='resident' then
  select raw_user_meta_data into metadata from auth.users where id=new.id;
  if metadata ? 'barangay_id' then
   select barangay_id into configured from public.barangay_localities where resident_registration_enabled;
   if (select count(*) from public.barangay_localities where resident_registration_enabled)<>1 or new.barangay_id is distinct from configured then
    raise exception 'registration_locality_not_configured' using errcode='22023';
   end if;
  end if;
  if not exists(select 1 from auth.identities where user_id=new.id and provider in ('google','apple')) then
   if metadata ? 'registration_gps' then new.registration_location:=nullif(metadata->'registration_gps','null'::jsonb); end if;
   if metadata ? 'registration_home' then new.registration_home_location:=nullif(metadata->'registration_home','null'::jsonb); end if;
  end if;
 elsif tg_op='UPDATE' and current_setting('role',true) in ('authenticated','anon')
   and current_setting('barangayan.profile_location_operation',true) is distinct from new.id::text
   and (new.registration_location is distinct from old.registration_location or new.registration_home_location is distinct from old.registration_home_location
     or new.location_verified is distinct from old.location_verified) then
  raise exception 'registration_location_operation_required' using errcode='42501';
 end if;
 if not barangayan_private.valid_location(new.registration_location) or not barangayan_private.valid_location(new.registration_home_location)
   or not barangayan_private.valid_location(new.verified_location) then raise exception 'invalid_coordinates' using errcode='22023'; end if;
 if tg_op='INSERT' then
  new.location_verified:=barangayan_private.location_inside(coalesce(new.registration_home_location,new.registration_location),geometry);
 end if;
 if new.verified_location is not null and (tg_op='INSERT' or new.verified_location is distinct from old.verified_location) then
  if barangayan_private.location_inside(new.verified_location,geometry) is distinct from true then raise exception 'location_outside_or_unavailable' using errcode='22023'; end if;
  new.location_verified_at:=clock_timestamp();
 elsif tg_op='UPDATE' and new.location_verified_at is distinct from old.location_verified_at and new.verified_location is not distinct from old.verified_location then
  new.location_verified_at:=old.location_verified_at;
 end if;
 return new;
end $$;

-- Apple supplies the (possibly private-relay) email on the Auth user and names, when
-- present, in identity data; subsequent sign-ins may omit names, which stay NULL until
-- the resident completes their profile. Same advisory lock as completion/Google.
create function barangayan_private.provision_apple_resident(p_uid uuid) returns uuid
language plpgsql security invoker set search_path='' as $$
declare v_email text; v_metadata jsonb; v_profile public.profiles;
 v_locality public.barangay_localities; v_first text; v_last text;
begin
 if p_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_uid::text,1));
 select u.email,i.identity_data into v_email,v_metadata
 from auth.users u join auth.identities i on i.user_id=u.id and i.provider='apple'
 where u.id=p_uid and not coalesce(u.is_anonymous,false)
 order by i.created_at,i.id limit 1;
 if not found then raise exception 'apple_identity_required' using errcode='42501'; end if;
 select * into v_profile from public.profiles where id=p_uid for update;
 if found then
  if v_profile.deleted_at is not null then raise exception 'forbidden' using errcode='42501'; end if;
  return p_uid;
 end if;
 begin
  select * into strict v_locality from public.barangay_localities
  where resident_registration_enabled for share;
 exception when no_data_found or too_many_rows then
  raise exception 'registration_locality_not_configured' using errcode='22023';
 end;
 select first_name,last_name into v_first,v_last from barangayan_private.google_resident_names(coalesce(v_metadata,'{}'::jsonb));
 insert into public.profiles(id,barangay_id,role,full_name,first_name,last_name,email,city,province)
 values(p_uid,v_locality.barangay_id,'resident',concat_ws(' ',v_first,v_last),v_first,v_last,v_email,v_locality.city,v_locality.province)
 on conflict(id) do nothing;
 return p_uid;
end $$;

create function barangayan_private.create_apple_resident_profile() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 perform barangayan_private.provision_apple_resident(new.user_id);
 return new;
end $$;
create trigger create_apple_resident_profile after insert on auth.identities
for each row when (new.provider='apple')
execute function barangayan_private.create_apple_resident_profile();

create function barangayan_private.ensure_apple_resident_profile() returns uuid
language plpgsql security definer set search_path='' as $$
begin
 return barangayan_private.provision_apple_resident((select auth.uid()));
end $$;
create function public.ensure_apple_resident_profile() returns uuid
language sql security invoker set search_path='' as $$
 select barangayan_private.ensure_apple_resident_profile()
$$;
revoke all on function barangayan_private.provision_apple_resident(uuid),barangayan_private.create_apple_resident_profile(),
 barangayan_private.ensure_apple_resident_profile(),public.ensure_apple_resident_profile() from public,anon,authenticated;
grant execute on function barangayan_private.ensure_apple_resident_profile(),public.ensure_apple_resident_profile() to authenticated;
comment on function public.ensure_apple_resident_profile() is
 'Idempotently creates the authenticated Apple resident''s minimal profile. Auth supplies identity/email; configuration supplies tenant. Does not complete required details or approve ID evidence.';

-- v1 keeps its strict three-value origin. An Apple account has no Google identity, so
-- the legacy clients' derived mode remains conservative (recover a password first).
create or replace function barangayan_private.get_resident_account_setup_status() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid()); p public.profiles; lifecycle barangayan_private.resident_account_lifecycle;
begin
 if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 if not exists(select 1 from auth.users u where u.id=v_uid and not coalesce(u.is_anonymous,false)
  and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now())) then
  raise exception 'resident_identity_required' using errcode='42501'; end if;
 select * into p from public.profiles where id=v_uid;
 if found and (p.role<>'resident' or p.deleted_at is not null) then raise exception 'forbidden' using errcode='42501'; end if;
 select * into lifecycle from barangayan_private.resident_account_lifecycle where user_id=v_uid;
 if not found then raise exception 'resident_setup_state_unavailable' using errcode='55000'; end if;
 return jsonb_build_object('registrationOrigin',case when lifecycle.registration_origin='apple' then 'legacy' else lifecycle.registration_origin end,
  'profileComplete',barangayan_private.resident_profile_complete(p),'passwordSet',lifecycle.password_set,
  'hasGoogleIdentity',exists(select 1 from auth.identities i where i.user_id=v_uid and i.provider='google'));
end $$;

-- v2: provider-aware contract for iOS. Unknown providers are surfaced, not hidden, so
-- the client can fail closed on a value it does not understand.
create function barangayan_private.get_resident_account_setup_status_v2() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_uid uuid:=(select auth.uid()); p public.profiles; lifecycle barangayan_private.resident_account_lifecycle;
 v_email text;
begin
 if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
 select u.email into v_email from auth.users u where u.id=v_uid and not coalesce(u.is_anonymous,false)
  and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now());
 if not found then raise exception 'resident_identity_required' using errcode='42501'; end if;
 select * into p from public.profiles where id=v_uid;
 if found and (p.role<>'resident' or p.deleted_at is not null) then raise exception 'forbidden' using errcode='42501'; end if;
 select * into lifecycle from barangayan_private.resident_account_lifecycle where user_id=v_uid;
 if not found then raise exception 'resident_setup_state_unavailable' using errcode='55000'; end if;
 return jsonb_build_object('contractVersion',2,
  'registrationOrigin',lifecycle.registration_origin,
  'profileComplete',barangayan_private.resident_profile_complete(p),
  'passwordSet',lifecycle.password_set,
  'identityProviders',coalesce((select jsonb_agg(distinct i.provider order by i.provider) from auth.identities i where i.user_id=v_uid),'[]'::jsonb),
  'hasGoogleIdentity',exists(select 1 from auth.identities i where i.user_id=v_uid and i.provider='google'),
  'hasAppleIdentity',exists(select 1 from auth.identities i where i.user_id=v_uid and i.provider='apple'),
  'emailIsPrivateRelay',coalesce(lower(v_email) like '%@privaterelay.appleid.com',false));
end $$;
create function public.get_resident_account_setup_status_v2() returns jsonb
language sql stable security invoker set search_path='' as $$ select barangayan_private.get_resident_account_setup_status_v2() $$;
revoke all on function barangayan_private.get_resident_account_setup_status_v2(),public.get_resident_account_setup_status_v2() from public,anon,authenticated,service_role;
grant execute on function barangayan_private.get_resident_account_setup_status_v2(),public.get_resident_account_setup_status_v2() to authenticated;
comment on function public.get_resident_account_setup_status_v2() is
 'Caller-only, provider-aware resident setup status for iOS (contractVersion 2). Null passwordSet means unresolved legacy provenance. The v1 function keeps its strict shape for Android/web.';

notify pgrst,'reload schema';
commit;-- Resident iOS Phase 17 (P17-T01/T02/T03/T07): durable server-backed notification inbox,
-- delivery outbox, per-kind preferences and the worker contract for Expo Push / APNs.
--
-- Design (plan §3 "Required notification architecture", P03-T07 contract):
--   * An event row, its resident inbox row and its outbox row are created by the same
--     statement that observes the source change (AFTER trigger), so none exists without
--     the others. Events are de-duplicated per (recipient, dedupe_key).
--   * The inbox is the resident-visible record. Its text is generic and written here, never
--     copied from a source row (no titles, addresses, names or reporter data), and its
--     destination is a versioned {v,kind,id} reference, never a URL or a snapshot.
--   * Preferences are applied when the worker claims a row (send time), not when the event is
--     created. They control phone alerts only; the inbox always records the event.
--   * Events, outbox and delivery tickets live in barangayan_private (no API exposure). The
--     sender runs as service_role and talks to them only through the notification_worker_*
--     functions below, which no other role can execute.
--   * Inbox read state is independent of announcement_reads and incidents.resolved_read_at.
--   * Client realtime remains a refresh signal; nothing here is a background-delivery promise.

-- ===== Preferences =====
create table if not exists public.notification_preferences (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  kinds jsonb not null default '{}'::jsonb check (jsonb_typeof(kinds)='object'),
  updated_at timestamptz not null default now()
);
alter table public.notification_preferences enable row level security;
drop policy if exists "residents read their notification preferences" on public.notification_preferences;
create policy "residents read their notification preferences" on public.notification_preferences
  for select to authenticated using (user_id=(select auth.uid()));
revoke all on public.notification_preferences from public,anon,authenticated;
grant select on public.notification_preferences to authenticated;
grant all on public.notification_preferences to service_role;

-- ===== Events (private) =====
create table if not exists barangayan_private.notification_events (
  id uuid primary key default gen_random_uuid(),
  barangay_id uuid not null references public.barangays(id),
  recipient_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null check (kind in ('request_status','payment','incident_status','announcement','medical_drive','health_registration')),
  subject_type text not null check (subject_type in ('request','incident','announcement','drive','registration')),
  subject_id uuid not null,
  dedupe_key text not null check (char_length(dedupe_key) between 1 and 200),
  payload_version integer not null default 1 check (payload_version=1),
  created_at timestamptz not null default now(),
  unique (recipient_id, dedupe_key)
);
create index if not exists notification_events_created_idx on barangayan_private.notification_events(created_at);

-- A destination is exactly {"v":1,"kind":<allowlisted>,"id":<uuid>}.
create or replace function barangayan_private.valid_notification_destination(d jsonb) returns boolean
language sql immutable set search_path='' as $$
  select jsonb_typeof(d)='object'
     and (select count(*) from jsonb_object_keys(d))=3
     and d->>'v'='1'
     and d->>'kind' in ('request','incident','announcement','drive','registration')
     and (d->>'id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
$$;

-- ===== Inbox (resident-visible) =====
create table if not exists public.notification_inbox (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null unique references barangayan_private.notification_events(id) on delete cascade,
  recipient_id uuid not null references public.profiles(id) on delete cascade,
  kind text not null check (kind in ('request_status','payment','incident_status','announcement','medical_drive','health_registration')),
  title text not null check (char_length(title) between 1 and 80),
  body text not null check (char_length(body) between 1 and 200),
  destination jsonb not null check (barangayan_private.valid_notification_destination(destination)),
  created_at timestamptz not null default now(),
  read_at timestamptz
);
create index if not exists notification_inbox_owner_idx on public.notification_inbox(recipient_id, created_at desc, id desc);
create index if not exists notification_inbox_unread_idx on public.notification_inbox(recipient_id) where read_at is null;
alter table public.notification_inbox enable row level security;
drop policy if exists "residents read their inbox" on public.notification_inbox;
drop policy if exists "residents mark their inbox read" on public.notification_inbox;
create policy "residents read their inbox" on public.notification_inbox for select to authenticated
  using (recipient_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=recipient_id and p.deleted_at is null));
create policy "residents mark their inbox read" on public.notification_inbox for update to authenticated
  using (recipient_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=recipient_id and p.deleted_at is null))
  with check (recipient_id=(select auth.uid()));
-- Residents may change read_at and nothing else: the privilege is column-level.
revoke all on public.notification_inbox from public,anon,authenticated;
grant select on public.notification_inbox to authenticated;
grant update (read_at) on public.notification_inbox to authenticated;
grant all on public.notification_inbox to service_role;

-- ===== Outbox and delivery tickets (private) =====
create table if not exists barangayan_private.notification_outbox (
  id uuid primary key default gen_random_uuid(),
  inbox_id uuid not null unique references public.notification_inbox(id) on delete cascade,
  recipient_id uuid not null references public.profiles(id) on delete cascade,
  state text not null default 'pending' check (state in ('pending','sending','sent','skipped','dead')),
  attempt_count integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  claimed_at timestamptz,
  last_error text check (char_length(last_error)<=200),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  finished_at timestamptz
);
create index if not exists notification_outbox_due_idx on barangayan_private.notification_outbox(next_attempt_at) where state in ('pending','sending');
create index if not exists notification_outbox_finished_idx on barangayan_private.notification_outbox(finished_at) where finished_at is not null;

create table if not exists barangayan_private.notification_deliveries (
  id uuid primary key default gen_random_uuid(),
  outbox_id uuid not null references barangayan_private.notification_outbox(id) on delete cascade,
  expo_push_token text not null,
  ticket_id text,
  -- accepted: Expo took the message (ticket ok). provider_ok: Expo's receipt says APNs took it.
  -- Neither means the phone showed it. expired: no receipt within the retention window.
  state text not null default 'accepted' check (state in ('accepted','provider_ok','error','expired')),
  error_code text check (char_length(error_code)<=60),
  sent_at timestamptz not null default now(),
  receipt_checked_at timestamptz
);
create index if not exists notification_deliveries_receipt_idx on barangayan_private.notification_deliveries(sent_at) where state='accepted';

revoke all on all tables in schema barangayan_private from public,anon,authenticated;
grant all on barangayan_private.notification_events, barangayan_private.notification_outbox, barangayan_private.notification_deliveries to service_role;

-- ===== Event creation =====
-- One statement writes the event, the inbox row and the outbox row for every eligible
-- recipient. A recipient is a non-deleted resident of the given barangay; anyone else is
-- dropped. Re-emitting the same dedupe key for the same recipient writes nothing.
create or replace function barangayan_private.emit_notification(
  p_recipients uuid[], p_barangay_id uuid, p_kind text, p_subject_type text, p_subject_id uuid,
  p_dedupe_key text, p_title text, p_body text) returns integer
language plpgsql security definer set search_path='' as $$
declare v_count integer;
begin
  with targets as (
    select p.id from public.profiles p
     where p.id=any(p_recipients) and p.role='resident' and p.deleted_at is null and p.barangay_id=p_barangay_id
  ), ev as (
    insert into barangayan_private.notification_events(barangay_id,recipient_id,kind,subject_type,subject_id,dedupe_key)
    select p_barangay_id,t.id,p_kind,p_subject_type,p_subject_id,p_dedupe_key from targets t
    on conflict (recipient_id,dedupe_key) do nothing
    returning id,recipient_id
  ), ib as (
    insert into public.notification_inbox(event_id,recipient_id,kind,title,body,destination)
    select e.id,e.recipient_id,p_kind,p_title,p_body,jsonb_build_object('v',1,'kind',p_subject_type,'id',p_subject_id) from ev e
    returning id,recipient_id
  )
  insert into barangayan_private.notification_outbox(inbox_id,recipient_id) select i.id,i.recipient_id from ib i;
  get diagnostics v_count = row_count;
  return v_count;
end $$;

-- A failed notification must never roll back the operational change that caused it.
create or replace function barangayan_private.notify_request_change() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=(select auth.uid()); v_title text; v_body text; v_kind text; v_key text;
begin
  if new.deleted_at is not null or v_actor is not distinct from new.resident_id then return null; end if;
  if new.payment_status is distinct from old.payment_status and new.payment_status in ('paid','waived') then
    v_kind:='payment'; v_title:='Payment update';
    v_body:=case new.payment_status when 'paid' then 'Your payment was received.' else 'No payment is due for your request.' end;
    v_key:='request:'||new.id||':payment:'||new.payment_status;
    perform barangayan_private.emit_notification(array[new.resident_id],new.barangay_id,v_kind,'request',new.id,v_key,v_title,v_body);
  end if;
  if new.status is distinct from old.status and new.status in ('in_progress','ready_for_pickup','completed','cancelled') then
    v_kind:='request_status';
    v_title:=case new.status when 'ready_for_pickup' then 'Request ready' else 'Request update' end;
    v_body:=case new.status
      when 'in_progress' then 'Your document request is being processed.'
      when 'ready_for_pickup' then 'Your document is ready for pickup.'
      when 'completed' then 'Your document request is complete.'
      else 'Your document request was cancelled.' end;
    v_key:='request:'||new.id||':status:'||new.status;
    perform barangayan_private.emit_notification(array[new.resident_id],new.barangay_id,v_kind,'request',new.id,v_key,v_title,v_body);
  end if;
  return null;
exception when others then
  raise warning 'notify_request_change failed: %',sqlstate;
  return null;
end $$;

create or replace function barangayan_private.notify_incident_change() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.deleted_at is not null or new.reporter_id is null or new.reporter_id is not distinct from (select auth.uid())
     or new.status not in ('in_progress','resolved','unresolved') then return null; end if;
  perform barangayan_private.emit_notification(array[new.reporter_id],new.barangay_id,'incident_status','incident',new.id,
    'incident:'||new.id||':status:'||new.status,'Report update','Your report has a new status.');
  return null;
exception when others then
  raise warning 'notify_incident_change failed: %',sqlstate;
  return null;
end $$;

create or replace function barangayan_private.notify_announcement() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.deleted_at is not null or new.published_at>now() then return null; end if;
  perform barangayan_private.emit_notification(
    (select coalesce(array_agg(p.id),'{}') from public.profiles p where p.barangay_id=new.barangay_id and p.role='resident' and p.deleted_at is null),
    new.barangay_id,'announcement','announcement',new.id,'announcement:'||new.id,'New announcement','Your barangay posted a new announcement.');
  return null;
exception when others then
  raise warning 'notify_announcement failed: %',sqlstate;
  return null;
end $$;

create or replace function barangayan_private.notify_medical_drive() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.deleted_at is not null or not new.is_active then return null; end if;
  perform barangayan_private.emit_notification(
    (select coalesce(array_agg(p.id),'{}') from public.profiles p where p.barangay_id=new.barangay_id and p.role='resident' and p.deleted_at is null),
    new.barangay_id,'medical_drive','drive',new.id,'drive:'||new.id,'New medical drive','A new medical drive is open in your barangay.');
  return null;
exception when others then
  raise warning 'notify_medical_drive failed: %',sqlstate;
  return null;
end $$;

create or replace function barangayan_private.notify_drive_registration() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_barangay uuid;
begin
  if new.status not in ('confirmed','attended','cancelled') or new.user_id is not distinct from (select auth.uid()) then return null; end if;
  select d.barangay_id into v_barangay from public.medical_drives d where d.id=new.drive_id;
  if v_barangay is null then return null; end if;
  perform barangayan_private.emit_notification(array[new.user_id],v_barangay,'health_registration','registration',new.id,
    'registration:'||new.id||':status:'||new.status,'Registration update','Your medical drive registration has a new status.');
  return null;
exception when others then
  raise warning 'notify_drive_registration failed: %',sqlstate;
  return null;
end $$;

drop trigger if exists z_notify_request_change on public.service_requests;
create trigger z_notify_request_change after update of status,payment_status on public.service_requests
  for each row when (old.status is distinct from new.status or old.payment_status is distinct from new.payment_status)
  execute function barangayan_private.notify_request_change();
drop trigger if exists z_notify_incident_change on public.incidents;
create trigger z_notify_incident_change after update of status on public.incidents
  for each row when (old.status is distinct from new.status)
  execute function barangayan_private.notify_incident_change();
drop trigger if exists z_notify_announcement on public.announcements;
create trigger z_notify_announcement after insert on public.announcements
  for each row execute function barangayan_private.notify_announcement();
drop trigger if exists z_notify_medical_drive on public.medical_drives;
create trigger z_notify_medical_drive after insert on public.medical_drives
  for each row execute function barangayan_private.notify_medical_drive();
drop trigger if exists z_notify_drive_registration on public.drive_registrations;
create trigger z_notify_drive_registration after update of status on public.drive_registrations
  for each row when (old.status is distinct from new.status)
  execute function barangayan_private.notify_drive_registration();

revoke all on function barangayan_private.emit_notification(uuid[],uuid,text,text,uuid,text,text,text) from public,anon,authenticated;
revoke all on function barangayan_private.notify_request_change(),barangayan_private.notify_incident_change(),barangayan_private.notify_announcement(),
  barangayan_private.notify_medical_drive(),barangayan_private.notify_drive_registration() from public,anon,authenticated;

-- ===== Resident operations =====
-- Preferences: the global switch stays on profiles.push_notifications_enabled (migration 0063);
-- per-kind switches are merged into notification_preferences.kinds. Both only ever change the
-- caller's own rows.
create or replace function public.set_notification_preferences(p_push_enabled boolean default null, p_kinds jsonb default null)
returns table(push_enabled boolean, kinds jsonb)
language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare v_uid uuid:=(select auth.uid()); v_key text; v_val jsonb;
begin
  if v_uid is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles p where p.id=v_uid and p.role='resident' and p.deleted_at is null) then
    raise exception 'forbidden' using errcode='42501';
  end if;
  if p_kinds is not null then
    if jsonb_typeof(p_kinds)<>'object' or (select count(*) from jsonb_object_keys(p_kinds))>10 then
      raise exception 'invalid_notification_preferences' using errcode='22023';
    end if;
    for v_key,v_val in select * from jsonb_each(p_kinds) loop
      if v_key not in ('request_status','payment','incident_status','announcement','medical_drive','health_registration')
         or jsonb_typeof(v_val)<>'boolean' then
        raise exception 'invalid_notification_preferences' using errcode='22023';
      end if;
    end loop;
    insert into public.notification_preferences as np(user_id,kinds) values (v_uid,p_kinds)
    on conflict (user_id) do update set kinds=np.kinds||excluded.kinds, updated_at=now();
  end if;
  if p_push_enabled is not null then
    update public.profiles set push_notifications_enabled=p_push_enabled where id=v_uid;
  end if;
  return query select p.push_notifications_enabled,coalesce((select np.kinds from public.notification_preferences np where np.user_id=v_uid),'{}'::jsonb)
    from public.profiles p where p.id=v_uid;
end $$;

-- Offline-logout recovery. A device that signed out without reaching the server has no session to
-- remove its token with, so this is callable without one: possession of the token is the proof, and
-- a push token is delivered only to the app on the device that owns it and to this server. It can
-- only ever remove a delivery address (never read or change anything else), it answers the same
-- whether or not the token existed (no oracle), and a token's format is checked so it cannot be
-- used to probe. The app re-registers its token on the next eligible session, so a wrongly removed
-- token costs at most alerts until the device is next opened.
create or replace function public.release_push_token(p_expo_push_token text) returns void
language plpgsql security definer set search_path='' as $$
begin
  if p_expo_push_token is null or char_length(p_expo_push_token)>200
     or p_expo_push_token !~ '^Expo(nent)?PushToken\[[A-Za-z0-9_-]+\]$' then
    raise exception 'invalid_push_token' using errcode='22023';
  end if;
  delete from public.push_tokens where expo_push_token=p_expo_push_token;
end $$;

revoke all on function public.set_notification_preferences(boolean,jsonb) from public,anon;
revoke all on function public.release_push_token(text) from public;
grant execute on function public.set_notification_preferences(boolean,jsonb) to authenticated,service_role;
grant execute on function public.release_push_token(text) to anon,authenticated,service_role;

-- ===== Sender (service_role only) =====
-- The sender claims due rows, applies the resident's preferences at that moment, sends to the
-- resident's current tokens through Expo Push, and reports tickets, failures and receipts back.

create or replace function barangayan_private.notification_retry(p_outbox_id uuid, p_error text) returns text
language plpgsql security definer set search_path='' as $$
declare v_attempts integer; v_state text;
begin
  select attempt_count into v_attempts from barangayan_private.notification_outbox where id=p_outbox_id;
  if not found then return null; end if;
  if v_attempts>=5 then
    update barangayan_private.notification_outbox set state='dead',last_error=left(p_error,200),finished_at=now(),updated_at=now() where id=p_outbox_id;
    return 'dead';
  end if;
  update barangayan_private.notification_outbox
     set state='pending',last_error=left(p_error,200),claimed_at=null,updated_at=now(),
         next_attempt_at=now()+make_interval(secs=>(array[60,300,900,3600])[least(greatest(v_attempts,1),4)])
   where id=p_outbox_id;
  return 'pending';
end $$;

create or replace function public.notification_worker_claim(p_limit integer default 50)
returns table(outbox_id uuid, inbox_id uuid, kind text, title text, body text, destination jsonb, tokens text[], attempt integer)
language plpgsql security definer set search_path='' as $$
declare r record; v_tokens text[]; v_reason text;
begin
  for r in
    select o.id as oid,o.inbox_id as iid,o.recipient_id as rid,o.attempt_count as tries,o.created_at as made,i.kind as ikind,i.title as ititle,i.body as ibody,i.destination as idest
      from barangayan_private.notification_outbox o join public.notification_inbox i on i.id=o.inbox_id
     where (o.state='pending' and o.next_attempt_at<=now()) or (o.state='sending' and o.claimed_at<now()-interval '5 minutes')
     order by o.next_attempt_at
     limit greatest(1,least(coalesce(p_limit,50),100))
     for update of o skip locked
  loop
    v_reason:=null; v_tokens:=null;
    if r.tries>=5 then
      update barangayan_private.notification_outbox set state='dead',last_error='abandoned',finished_at=now(),updated_at=now() where id=r.oid;
      continue;
    end if;
    if r.made<now()-interval '24 hours' then v_reason:='stale';
    elsif not exists(select 1 from public.profiles p where p.id=r.rid and p.role='resident' and p.deleted_at is null and p.push_notifications_enabled) then v_reason:='opted_out';
    elsif exists(select 1 from public.notification_preferences np where np.user_id=r.rid and np.kinds->>r.ikind='false') then v_reason:='kind_off';
    else
      select array_agg(x.t) into v_tokens from (
        select t.expo_push_token as t from public.push_tokens t
         where t.user_id=r.rid and t.last_used_at>now()-interval '60 days'
         order by t.last_used_at desc limit 10) x;
      if v_tokens is null then v_reason:='no_token'; end if;
    end if;
    if v_reason is not null then
      update barangayan_private.notification_outbox set state='skipped',last_error=v_reason,finished_at=now(),updated_at=now() where id=r.oid;
      continue;
    end if;
    update barangayan_private.notification_outbox set state='sending',claimed_at=now(),attempt_count=attempt_count+1,updated_at=now() where id=r.oid;
    outbox_id:=r.oid; inbox_id:=r.iid; kind:=r.ikind; title:=r.ititle; body:=r.ibody; destination:=r.idest; tokens:=v_tokens; attempt:=r.tries+1;
    return next;
  end loop;
end $$;

-- p_tickets: [{"token":"...","status":"ok","id":"..."} | {"token":"...","status":"error","error":"DeviceNotRegistered"}]
create or replace function public.notification_worker_record_tickets(p_outbox_id uuid, p_tickets jsonb) returns text
language plpgsql security definer set search_path='' as $$
declare t jsonb; v_ok integer:=0; v_gone integer:=0; v_total integer:=0; v_error text;
begin
  if jsonb_typeof(p_tickets)<>'array' or jsonb_array_length(p_tickets)>20 then raise exception 'invalid_tickets' using errcode='22023'; end if;
  perform 1 from barangayan_private.notification_outbox where id=p_outbox_id and state='sending' for update;
  if not found then raise exception 'outbox_not_claimed' using errcode='P0002'; end if;
  for t in select * from jsonb_array_elements(p_tickets) loop
    if jsonb_typeof(t)<>'object' or jsonb_typeof(t->'token')<>'string' or t->>'status' not in ('ok','error') then
      raise exception 'invalid_tickets' using errcode='22023';
    end if;
    v_total:=v_total+1;
    if t->>'status'='ok' then
      v_ok:=v_ok+1;
      insert into barangayan_private.notification_deliveries(outbox_id,expo_push_token,ticket_id,state) values (p_outbox_id,t->>'token',left(t->>'id',100),'accepted');
    else
      v_error:=left(coalesce(t->>'error','unknown'),60);
      insert into barangayan_private.notification_deliveries(outbox_id,expo_push_token,state,error_code) values (p_outbox_id,t->>'token','error',v_error);
      if v_error='DeviceNotRegistered' then
        v_gone:=v_gone+1;
        delete from public.push_tokens where expo_push_token=t->>'token';
      end if;
    end if;
  end loop;
  if v_ok>0 then
    update barangayan_private.notification_outbox set state='sent',last_error=null,finished_at=now(),updated_at=now() where id=p_outbox_id;
    return 'sent';
  elsif v_total>0 and v_gone=v_total then
    update barangayan_private.notification_outbox set state='skipped',last_error='device_not_registered',finished_at=now(),updated_at=now() where id=p_outbox_id;
    return 'skipped';
  end if;
  return barangayan_private.notification_retry(p_outbox_id,'ticket_error:'||coalesce(v_error,'none'));
end $$;

create or replace function public.notification_worker_fail(p_outbox_id uuid, p_error text) returns text
language plpgsql security definer set search_path='' as $$
begin
  perform 1 from barangayan_private.notification_outbox where id=p_outbox_id and state='sending' for update;
  if not found then raise exception 'outbox_not_claimed' using errcode='P0002'; end if;
  return barangayan_private.notification_retry(p_outbox_id,regexp_replace(coalesce(p_error,'unknown'),'Expo(nent)?PushToken\[[^]]*\]','[token]','g'));
end $$;

-- Tickets whose receipt is due (at least 15 minutes old, inside Expo's 24 hour retention).
create or replace function public.notification_worker_due_receipts(p_limit integer default 300)
returns table(delivery_id uuid, ticket_id text)
language plpgsql security definer set search_path='' as $$
begin
  update barangayan_private.notification_deliveries set state='expired',receipt_checked_at=now()
   where state='accepted' and sent_at<=now()-interval '23 hours';
  return query select d.id,d.ticket_id from barangayan_private.notification_deliveries d
   where d.state='accepted' and d.ticket_id is not null and d.sent_at<=now()-interval '15 minutes'
   order by d.sent_at limit greatest(1,least(coalesce(p_limit,300),1000));
end $$;

-- p_receipts: [{"delivery_id":"<uuid>","status":"ok"} | {"delivery_id":"<uuid>","status":"error","error":"DeviceNotRegistered"}]
create or replace function public.notification_worker_record_receipts(p_receipts jsonb) returns integer
language plpgsql security definer set search_path='' as $$
declare r jsonb; v_count integer:=0; v_error text; v_token text; v_updated integer;
begin
  if jsonb_typeof(p_receipts)<>'array' or jsonb_array_length(p_receipts)>1000 then raise exception 'invalid_receipts' using errcode='22023'; end if;
  for r in select * from jsonb_array_elements(p_receipts) loop
    if jsonb_typeof(r)<>'object' or r->>'status' not in ('ok','error')
       or (r->>'delivery_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'invalid_receipts' using errcode='22023';
    end if;
    if r->>'status'='ok' then
      update barangayan_private.notification_deliveries set state='provider_ok',receipt_checked_at=now()
       where id=(r->>'delivery_id')::uuid and state='accepted';
    else
      v_error:=left(coalesce(r->>'error','unknown'),60);
      update barangayan_private.notification_deliveries set state='error',error_code=v_error,receipt_checked_at=now()
       where id=(r->>'delivery_id')::uuid and state='accepted' returning expo_push_token into v_token;
      if v_error='DeviceNotRegistered' and v_token is not null then
        delete from public.push_tokens where expo_push_token=v_token;
      end if;
    end if;
    get diagnostics v_updated = row_count;
    v_count:=v_count+v_updated;
  end loop;
  return v_count;
end $$;

-- Operational counts the sender returns on every run so a monitor can alert on them.
create or replace function public.notification_worker_health()
returns table(pending_total integer, oldest_pending_seconds integer, dead_last_24h integer, ticket_errors_last_24h integer, unreceipted_over_1h integer)
language sql security definer set search_path='' as $$
  select (select count(*)::int from barangayan_private.notification_outbox where state in ('pending','sending')),
         (select coalesce(extract(epoch from now()-min(next_attempt_at))::int,0) from barangayan_private.notification_outbox where state in ('pending','sending') and next_attempt_at<=now()),
         (select count(*)::int from barangayan_private.notification_outbox where state='dead' and finished_at>now()-interval '24 hours'),
         (select count(*)::int from barangayan_private.notification_deliveries where state='error' and sent_at>now()-interval '24 hours'),
         (select count(*)::int from barangayan_private.notification_deliveries where state='accepted' and sent_at<now()-interval '1 hour')
$$;

-- Retention (P03-T07): read inbox rows 90 days after reading, finished outbox rows 30 days, events 180 days.
create or replace function public.notification_worker_purge() returns table(inbox_deleted integer, outbox_deleted integer, events_deleted integer)
language plpgsql security definer set search_path='' as $$
declare a integer; b integer; c integer;
begin
  delete from barangayan_private.notification_outbox where finished_at<now()-interval '30 days';
  get diagnostics b = row_count;
  delete from public.notification_inbox where read_at<now()-interval '90 days';
  get diagnostics a = row_count;
  delete from barangayan_private.notification_events e where e.created_at<now()-interval '180 days'
    and not exists(select 1 from public.notification_inbox i where i.event_id=e.id);
  get diagnostics c = row_count;
  return query select a,b,c;
end $$;

revoke all on function barangayan_private.notification_retry(uuid,text) from public,anon,authenticated;
revoke all on function public.notification_worker_claim(integer),public.notification_worker_record_tickets(uuid,jsonb),
  public.notification_worker_fail(uuid,text),public.notification_worker_due_receipts(integer),
  public.notification_worker_record_receipts(jsonb),public.notification_worker_health(),public.notification_worker_purge() from public,anon,authenticated;
grant execute on function public.notification_worker_claim(integer),public.notification_worker_record_tickets(uuid,jsonb),
  public.notification_worker_fail(uuid,text),public.notification_worker_due_receipts(integer),
  public.notification_worker_record_receipts(jsonb),public.notification_worker_health(),public.notification_worker_purge() to service_role;

