    alter publication supabase_realtime add table public.notification_inbox;
  end if;
end $$;-- Resident iOS Phase 17 (P17-T01/T02/T03/T07): inbox, outbox, preferences, event creation and
-- the sender (worker) contract of migration 0135. Everything, fixtures included, lives in one
-- transaction that is rolled back.
begin;
